// ##################

import React, { useState, useEffect, useRef } from "react";
import { useLocation } from "@tanstack/react-router";
import {
  X,
  SendHorizontal,
  Calendar,
  Building2,
  Briefcase,
  FileQuestion,
  Bot,
} from "lucide-react";
import ImageWithFallback from "@/components/image-with-fallback";
import { motion, AnimatePresence } from "motion/react";

interface Message {
  id: string;
  sender: "user" | "bot";
  text: string;
  timestamp: string;
}

const IMG = "/assets/asty_3.png";
const FLOATING_AVATARS = [
  "/assets/asty_3.png",
  "/assets/asty_4.png",
  "/assets/asty_2.png",
];

const badgeTexts = ["Hai,\nASTY\ndisini!", "Asisten\nSafety\nKamu!"];

/**
 * Mendapatkan representasi waktu saat ini dalam format HH:MM.
 */
const getCurrentTime = (): string => {
  return new Date().toLocaleTimeString("id-ID", {
    hour: "2-digit",
    minute: "2-digit",
  });
};

import { formatWaNumber, getBotResponse } from "@/utils/chatbot-utils";
import { trpc } from "@/utils/trpc";
import { useMutation, useQuery } from "@tanstack/react-query";
import { authMeQueryOptions } from "@/utils/auth-query";

/**
 * Komponen Floating Chatbot Asty untuk membantu pengguna.
 */
export function AstyChatbot() {
  const location = useLocation();
  const pathname = location.pathname;

  // Cek apakah halaman saat ini diperbolehkan (Halaman publik & dashboard customer)
  const allowedPrefixes = [
    "/dashboard",
    "/katalog",
    "/profil",
    "/berita",
    "/pelatihan",
    "/login",
    "/register",
    "/verify",
    "/cart-pelatihan",
    "/pengujian",
  ];

  const isAllowed =
    pathname === "/" ||
    allowedPrefixes.some((prefix) => pathname.startsWith(prefix));
  const isInternal =
    pathname.startsWith("/back-office") ||
    pathname.startsWith("/employee") ||
    pathname.startsWith("/display-board") ||
    pathname.startsWith("/worksheets");

  const shouldShow = isAllowed && !isInternal;

  const { data: kbData } = useQuery({
    ...trpc.platform.chatbot.getAll.queryOptions(),
    enabled: shouldShow,
  });

  const { data: user } = useQuery({
    ...authMeQueryOptions(),
    enabled: shouldShow,
  });

  const { data: myOrders } = useQuery({
    ...trpc.pengujian.order.getAllOrders.queryOptions({ status: "all" }),
    enabled: !!user?.id && shouldShow,
  });

  const latestOrder = myOrders?.[0];

  const { data: waSetting } = useQuery({
    ...trpc.platform.setting.getByKey.queryOptions({ key: "chatbot_wa_number" }),
    enabled: shouldShow,
  });

  const askMutation = useMutation(
    trpc.platform.chatbot.ask.mutationOptions(),
  );

  // State Management
  const [isOpen, setIsOpen] = useState<boolean>(() => {
    if (typeof window !== "undefined") {
      const saved = sessionStorage.getItem("asty_chat_open");
      return saved === "true";
    }
    return false;
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    if (typeof window !== "undefined") {
      const saved = sessionStorage.getItem("asty_chat_messages");
      if (saved) {
        try {
          return JSON.parse(saved);
        } catch (e) {
          console.error("Gagal memuat histori chat Asty:", e);
        }
      }
    }
    return [
      {
        id: "welcome",
        sender: "bot",
        text: "Halo! 👋 Saya Asty (Asisten Safety), asisten virtual Balai K3 Samarinda.\n\nSaya siap membantu Anda mendapatkan informasi layanan pengujian, jadwal pelatihan K3 2026, profil balai, atau pertanyaan seputar K3 (Safety). Apa yang bisa saya bantu hari ini?",
        timestamp: getCurrentTime(),
      },
    ];
  });

  const [inputText, setInputText] = useState<string>("");
  const [isTyping, setIsTyping] = useState<boolean>(false);
  const [badgeTextIndex, setBadgeTextIndex] = useState<number>(0);
  const [avatarIndex, setAvatarIndex] = useState<number>(0);
  const [showBadgeText, setShowBadgeText] = useState<boolean>(true);

  const msgsEndRef = useRef<HTMLDivElement>(null);

  // Simpan status chat open/close ke sessionStorage
  useEffect(() => {
    sessionStorage.setItem("asty_chat_open", String(isOpen));
  }, [isOpen]);

  // Simpan histori chat ke sessionStorage
  useEffect(() => {
    sessionStorage.setItem("asty_chat_messages", JSON.stringify(messages));
    scrollToBottom();
  }, [messages]);

  // Scroll otomatis ke dasar list chat
  const scrollToBottom = () => {
    msgsEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  // Rotasi teks melayang dan avatar setiap 3 detik
  useEffect(() => {
    if (isOpen || !shouldShow) return;

    const interval = setInterval(() => {
      // Fade out badge text, switch index, then fade in
      setShowBadgeText(false);
      setTimeout(() => {
        setAvatarIndex((prev) => {
          const next = (prev + 1) % FLOATING_AVATARS.length;
          if (next === 0) {
            // Jika kembali menampilkan asty_3.png (index 0), ganti teks badge berikutnya
            setBadgeTextIndex((tPrev) => (tPrev === 0 ? 1 : 0));
          }
          return next;
        });
        setShowBadgeText(true);
      }, 300); // durasi fade-out
    }, 3000);

    return () => clearInterval(interval);
  }, [isOpen, shouldShow]);

  if (!shouldShow) return null;

  // Handle pengiriman pesan
  const handleSend = (text: string) => {
    if (!text.trim() || isTyping) return;

    const userMsg: Message = {
      id: `msg-${Date.now()}`,
      sender: "user",
      text: text.trim(),
      timestamp: getCurrentTime(),
    };

    setMessages((prev) => [...prev, userMsg]);
    setInputText("");
    setIsTyping(true);

    const history = messages
      .filter((m) => m.id !== "welcome")
      .map((m) => ({
        role: (m.sender === "user" ? "user" : "model") as "user" | "model",
        text: m.text,
      }));

    askMutation.mutate(
      {
        message: text.trim(),
        history,
      },
      {
        onSuccess: (data: { text: string }) => {
          const botMsg: Message = {
            id: `msg-${Date.now() + 1}`,
            sender: "bot",
            text: data.text,
            timestamp: getCurrentTime(),
          };
          setMessages((prev) => [...prev, botMsg]);
          setIsTyping(false);
        },
        onError: () => {
          const botResponseText = getBotResponse(text, kbData ?? [], waSetting?.value, latestOrder);
          const botMsg: Message = {
            id: `msg-${Date.now() + 1}`,
            sender: "bot",
            text: botResponseText,
            timestamp: getCurrentTime(),
          };
          setMessages((prev) => [...prev, botMsg]);
          setIsTyping(false);
        },
      }
    );
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    handleSend(inputText);
  };

  const handleQuickReply = (question: string) => {
    handleSend(question);
  };

  const activeAvatar = FLOATING_AVATARS[avatarIndex] || "/assets/asty_3.png";

  return (
    <div className="fixed right-6 bottom-6 z-50 font-sans">
      {/* Inline styles for typing bouncing dot animation */}
      <style
        dangerouslySetInnerHTML={{
          __html: `
        @keyframes asty-bounce {
          0%, 80%, 100% { transform: translateY(0); }
          40% { transform: translateY(-6px); }
        }
        .asty-dot {
          animation: asty-bounce 1.4s infinite ease-in-out;
        }
        .asty-dot:nth-child(2) { animation-delay: 0.2s; }
        .asty-dot:nth-child(3) { animation-delay: 0.4s; }
      `,
        }}
      />

      <AnimatePresence>
        {!isOpen && (
          <motion.div
            initial={{ scale: 0, opacity: 0 }}
            animate={{
              scale: 1,
              opacity: 1,
              y: [0, -6, 0],
            }}
            exit={{ scale: 0, opacity: 0 }}
            transition={{
              scale: { duration: 0.3 },
              opacity: { duration: 0.3 },
              y: {
                duration: 4,
                repeat: Infinity,
                ease: "easeInOut",
              },
            }}
            className="group flex cursor-pointer items-center gap-3"
            onClick={() => setIsOpen(true)}
          >
            {/* Speech Bubble Badge */}
            <AnimatePresence mode="wait">
              {showBadgeText && avatarIndex === 0 && (
                <motion.div
                  initial={{ opacity: 0, x: 10, scale: 0.95 }}
                  animate={{ opacity: 1, x: 0, scale: 1 }}
                  exit={{ opacity: 0, x: 10, scale: 0.95 }}
                  transition={{
                    type: "spring",
                    stiffness: 350,
                    damping: 18,
                  }}
                  className="w-[80px] rounded-tl-xl rounded-tr-xl rounded-br-none rounded-bl-xl border border-blue-100 bg-white px-3 py-2 text-center text-[11px] font-semibold shadow-[0_4px_12px_rgba(16,97,214,0.12)] dark:border-slate-800 dark:bg-slate-900"
                >
                  <span className="block bg-gradient-to-br from-[#169AF9] to-[#0C74EA] bg-clip-text leading-tight whitespace-pre-line text-transparent">
                    {badgeTexts[badgeTextIndex]}
                  </span>
                </motion.div>
              )}
            </AnimatePresence>

            {/* Avatar Button */}
            <div className="relative flex h-15 w-15 items-center justify-center rounded-full border-2 border-white bg-white shadow-[0_4px_16px_rgba(16,97,214,0.2)] transition-transform duration-200 hover:scale-105 dark:border-slate-800 dark:bg-slate-900">
              <div className="relative flex h-[54px] w-[54px] items-center justify-center overflow-hidden rounded-full bg-sky-50 dark:bg-slate-800">
                <AnimatePresence mode="wait">
                  <motion.img
                    key={activeAvatar}
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.8 }}
                    transition={{ duration: 0.3 }}
                    src={activeAvatar}
                    alt="Asty"
                    className={`absolute inset-0 h-full w-full object-cover ${
                      activeAvatar.includes("asty_4") ? "" : "scale-x-[-1]"
                    }`}
                    onError={(e) => {
                      e.currentTarget.style.display = "none";
                      const parent = e.currentTarget.parentElement;
                      if (parent) {
                        parent.innerHTML = "<span class='text-2xl'>🤖</span>";
                      }
                    }}
                  />
                </AnimatePresence>
              </div>
              <span className="absolute right-0 bottom-0 flex h-3.5 w-3.5 items-center justify-center">
                <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-[#0AB54A] opacity-75" />
                <span className="relative inline-flex h-2.5 w-2.5 rounded-full border border-white bg-[#0AB54A] dark:border-slate-900" />
              </span>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 40, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 40, scale: 0.95 }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="flex h-[623px] max-h-[calc(100vh-100px)] w-[444px] max-w-[calc(100vw-32px)] flex-col overflow-hidden rounded-[30px] border border-[#AFCFFA] bg-[#F8FAFC] shadow-2xl dark:border-slate-800 dark:bg-slate-950"
          >
            {/* Header */}
            <div className="relative flex h-20 shrink-0 items-center justify-between bg-gradient-to-r from-[#1D4ED8] to-[#0E948B] px-6">
              <div className="flex items-center gap-3">
                <div className="relative flex h-10 w-10 items-center justify-center rounded-full bg-white shadow-sm">
                  <div className="flex h-9 w-9 items-center justify-center overflow-hidden rounded-full">
                    <ImageWithFallback
                      src={IMG}
                      alt="Asty"
                      className="h-full w-full"
                      imgClassName="w-full h-full object-cover"
                      fallbackIcon={Bot}
                    />
                  </div>
                  <span className="absolute right-0 bottom-0 h-2.5 w-2.5 rounded-full border border-white bg-[#0AB54A]" />
                </div>
                <div>
                  <h3 className="flex items-center gap-1 text-sm leading-tight font-semibold text-white">
                    Asty (Asisten Safety){" "}
                    <span className="text-yellow-300">✨</span>
                  </h3>
                  <p className="text-[10px] font-medium tracking-wider text-teal-100/90 uppercase">
                    BALAI K3 SAMARINDA
                  </p>
                </div>
              </div>
              <button
                onClick={() => setIsOpen(false)}
                className="flex h-8 w-8 items-center justify-center rounded-full text-white/80 transition-colors hover:bg-white/10 hover:text-white focus:outline-none"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            {/* Messages Area */}
            <div className="custom-scrollbar min-h-0 flex-1 space-y-4 overflow-y-auto bg-[#F8FAFC] px-5 py-4 dark:bg-slate-950">
              {messages.map((msg) => (
                <div
                  key={msg.id}
                  className={`flex ${msg.sender === "user" ? "justify-end" : "justify-start"} items-end gap-2`}
                >
                  {msg.sender === "bot" && (
                    <div className="flex h-[34px] w-[34px] shrink-0 items-center justify-center overflow-hidden rounded-full border border-[#f3f4f6] bg-white shadow-sm dark:border-slate-800 dark:bg-slate-800">
                      <ImageWithFallback
                        src={IMG}
                        alt="Asty"
                        className="h-full w-full"
                        imgClassName="w-full h-full object-cover"
                        fallbackIcon={Bot}
                      />
                    </div>
                  )}

                  <div
                    className={`flex max-w-[75%] flex-col ${msg.sender === "user" ? "items-end" : "items-start"}`}
                  >
                    <div
                      className={`px-4 py-3 text-xs leading-relaxed whitespace-pre-wrap shadow-sm ${
                        msg.sender === "user"
                          ? "rounded-t-xl rounded-br-none rounded-bl-xl bg-[#1061D6] text-white"
                          : "rounded-t-xl rounded-br-xl rounded-bl-none border border-[#EFEFEF] bg-white text-[#4D4D4D] dark:border-slate-800/80 dark:bg-slate-900 dark:text-slate-200"
                      }`}
                    >
                      {msg.text}
                    </div>
                    <span className="mt-1 px-1 text-[10px] text-gray-400 dark:text-slate-500">
                      {msg.timestamp}
                    </span>
                  </div>
                </div>
              ))}

              {isTyping && (
                <div className="flex items-end justify-start gap-2">
                  <div className="flex h-[34px] w-[34px] shrink-0 items-center justify-center overflow-hidden rounded-full border border-[#f3f4f6] bg-white shadow-sm dark:border-slate-800 dark:bg-slate-800">
                    <ImageWithFallback
                      src={IMG}
                      alt="Asty"
                      className="h-full w-full"
                      imgClassName="w-full h-full object-cover"
                      fallbackIcon={Bot}
                    />
                  </div>
                  <div className="flex flex-col items-start">
                    <div className="flex items-center gap-1 rounded-t-xl rounded-br-xl rounded-bl-none border border-[#EFEFEF] bg-white px-4 py-3 shadow-sm dark:border-slate-800/80 dark:bg-slate-900">
                      <div className="asty-dot h-1.5 w-1.5 rounded-full bg-gray-400 dark:bg-slate-500" />
                      <div className="asty-dot h-1.5 w-1.5 rounded-full bg-gray-400 dark:bg-slate-500" />
                      <div className="asty-dot h-1.5 w-1.5 rounded-full bg-gray-400 dark:bg-slate-500" />
                    </div>
                  </div>
                </div>
              )}
              <div ref={msgsEndRef} />
            </div>

            {/* Quick Replies */}
            <div className="scrollbar-none flex shrink-0 gap-2 overflow-x-auto border-t border-[#e5e7eb] bg-white px-4 py-2.5 whitespace-nowrap dark:border-slate-800/80 dark:bg-slate-900">
              <button
                onClick={() => handleQuickReply("Jadwal Pelatihan 2026")}
                className="inline-flex cursor-pointer items-center gap-1.5 rounded-full border border-blue-100 bg-blue-50/50 px-3 py-1.5 text-xs text-[#1D4ED8] transition-colors hover:bg-blue-100/60 dark:border-blue-900/50 dark:bg-blue-950/20 dark:text-blue-400 dark:hover:bg-blue-950/40"
              >
                <Calendar className="h-3.5 w-3.5" />
                Jadwal Pelatihan
              </button>
              <button
                onClick={() => handleQuickReply("Profil Balai K3 Samarinda")}
                className="inline-flex cursor-pointer items-center gap-1.5 rounded-full border border-blue-100 bg-blue-50/50 px-3 py-1.5 text-xs text-[#1D4ED8] transition-colors hover:bg-blue-100/60 dark:border-blue-900/50 dark:bg-blue-950/20 dark:text-blue-400 dark:hover:bg-blue-950/40"
              >
                <Building2 className="h-3.5 w-3.5" />
                Profil Balai
              </button>
              <button
                onClick={() =>
                  handleQuickReply("Apa saja layanan yang tersedia?")
                }
                className="inline-flex cursor-pointer items-center gap-1.5 rounded-full border border-blue-100 bg-blue-50/50 px-3 py-1.5 text-xs text-[#1D4ED8] transition-colors hover:bg-blue-100/60 dark:border-blue-900/50 dark:bg-blue-950/20 dark:text-blue-400 dark:hover:bg-blue-950/40"
              >
                <Briefcase className="h-3.5 w-3.5" />
                Daftar Layanan
              </button>
              <button
                onClick={() => handleQuickReply("Apa saja persyaratannya?")}
                className="inline-flex cursor-pointer items-center gap-1.5 rounded-full border border-blue-100 bg-blue-50/50 px-3 py-1.5 text-xs text-[#1D4ED8] transition-colors hover:bg-blue-100/60 dark:border-blue-900/50 dark:bg-blue-950/20 dark:text-blue-400 dark:hover:bg-blue-950/40"
              >
                <FileQuestion className="h-3.5 w-3.5" />
                Persyaratan
              </button>
            </div>

            {/* Input Form */}
            <div className="shrink-0 border-t border-[#e5e7eb] bg-white px-5 py-4 dark:border-slate-800/80 dark:bg-slate-900">
              <form
                onSubmit={handleFormSubmit}
                className="flex items-center gap-2.5"
              >
                <input
                  type="text"
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  placeholder="Tanya info layanan / jadwal pelatihan / tips K3..."
                  disabled={isTyping}
                  className="flex-1 rounded-full border border-transparent bg-[#EEEEEE] px-5 py-2.5 text-[11px] text-slate-800 transition-all outline-none placeholder:text-[#C8C8C8] focus:border-[#1061D6]/30 focus:bg-white disabled:opacity-75 dark:bg-slate-800/60 dark:text-slate-100 dark:placeholder:text-slate-500 dark:focus:bg-slate-800"
                />
                <button
                  type="submit"
                  disabled={!inputText.trim() || isTyping}
                  className="flex h-9.5 w-9.5 shrink-0 cursor-pointer items-center justify-center rounded-full bg-[#1061D6] text-white transition-colors hover:bg-[#0d4eb8] disabled:opacity-50 disabled:hover:bg-[#1061D6]"
                >
                  <SendHorizontal className="ml-0.5 h-4.5 w-4.5" />
                </button>
              </form>
              <div className="mt-2.5 text-center text-[9px] leading-snug text-gray-400 dark:text-slate-500">
                Asty dirancang untuk memberikan informasi layanan Balai K3
                Samarinda &amp; edukasi Keselamatan Kerja.
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

